```javascript
const assert = require('assert');

function expectThrow(fn, msg) {
  try {
    fn();
    assert.fail(`Expected throw: ${msg}`);
  } catch (e) {
    assert.strictEqual(e.message, 'INVALID_POSITIVE_INT', `Wrong error message for: ${msg}`);
  }
}

// --- 正常路径 ---
assert.strictEqual(parsePositiveInt(1), 1);
assert.strictEqual(parsePositiveInt(42), 42);
assert.strictEqual(parsePositiveInt(Number.MAX_SAFE_INTEGER), 9007199254740991);
assert.strictEqual(parsePositiveInt('1'), 1);
assert.strictEqual(parsePositiveInt('999'), 999);
assert.strictEqual(parsePositiveInt('  123  '), 123);
assert.strictEqual(parsePositiveInt(String(Number.MAX_SAFE_INTEGER)), 9007199254740991);

// --- number 边界与非法值 ---
expectThrow(() => parsePositiveInt(0), 'number zero');
expectThrow(() => parsePositiveInt(-1), 'negative number');
expectThrow(() => parsePositiveInt(1.5), 'non-integer number');
expectThrow(() => parsePositiveInt(NaN), 'NaN');
expectThrow(() => parsePositiveInt(Infinity), 'Infinity');
expectThrow(() => parsePositiveInt(-Infinity), '-Infinity');
expectThrow(() => parsePositiveInt(Number.MAX_SAFE_INTEGER + 1), 'exceeds safe integer');

// --- string 非法格式 ---
expectThrow(() => parsePositiveInt('0'), 'string zero');
expectThrow(() => parsePositiveInt('01'), 'leading zero');
expectThrow(() => parsePositiveInt('-5'), 'negative string');
expectThrow(() => parsePositiveInt('1.0'), 'decimal string');
expectThrow(() => parsePositiveInt('1e5'), 'scientific notation');
expectThrow(() => parsePositiveInt('12abc'), 'partial parse rejection');
expectThrow(() => parsePositiveInt('abc12'), 'prefix garbage');
expectThrow(() => parsePositiveInt('1 2'), 'internal space');
expectThrow(() => parsePositiveInt(''), 'empty string');
expectThrow(() => parsePositiveInt('   '), 'whitespace only');
expectThrow(() => parsePositiveInt('9007199254740993'), 'exceeds safe integer as string');
expectThrow(() => parsePositiveInt('+5'), 'plus sign');
expectThrow(() => parsePositiveInt('0x1F'), 'hex string');
expectThrow(() => parsePositiveInt('\t
42\r'), 'non-ASCII whitespace rejected');

// --- 非 number/string 类型 ---
expectThrow(() => parsePositiveInt(true), 'boolean');
expectThrow(() => parsePositiveInt(false), 'boolean false');
expectThrow(() => parsePositiveInt(null), 'null');
expectThrow(() => parsePositiveInt(undefined), 'undefined');
expectThrow(() => parsePositiveInt({}), 'object');
expectThrow(() => parsePositiveInt([]), 'array');
expectThrow(() => parsePositiveInt(Symbol('x')), 'symbol');
expectThrow(() => parsePositiveInt(() => {}), 'function');

console.log('All tests passed.');
```

